"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3229],{35427:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldController","desc":"Discovers shield-console instances via CollectionService tags and wires their\\nProximityPrompt to send `ReqRechargeShield` (mirroring TrainClient\'s refuel\\nprompt, including the \\"hold with no energy\\" early-out). On a successful\\nrecharge it plays a SoundManager SFX. Incoming `TrainShieldSync` packets are\\nalso bridged into `Signals.OnTrainShieldChanged`, kept as a push-side\\nextension seam; it currently has no subscribers -- `TrainShieldGuiController`\\nreads `TrainStateCache` instead. Each incoming snapshot is written to\\n`TrainStateCache` before that signal fires, so a late subscriber can still\\nrecover it.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldController.client.luau"}}')}}]);